import React, { useState, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import MatchList from "../components/MatchList";
import { getMatches } from "../api";

// Импорт логотипов (убедись, что файлы лежат в этой папке)
import plLogo from "../assets/leagues/premier-league.png";
import blLogo from "../assets/leagues/bundesliga.png";
import saLogo from "../assets/leagues/serie-a.png";
import pdLogo from "../assets/leagues/la-liga.png";
import flLogo from "../assets/leagues/ligue-1.png";

const SidebarLeagues = [
  { code: null, name: "ВСЕ МАТЧИ", shortName: "Все", logo: null },
  { code: "Premier_League", name: "Premier League", logo: plLogo },
  { code: "La_Liga", name: "La Liga", logo: pdLogo },
  { code: "Serie_A", name: "Serie A", logo: saLogo },
  { code: "Bundesliga", name: "Bundesliga", logo: blLogo },
  { code: "Ligue_1", name: "Ligue 1", logo: flLogo },
];

function HomePage() {
  const [allMatches, setAllMatches] = useState([]);
  const [displayMatches, setDisplayMatches] = useState([]);
  const [loading, setLoading] = useState(true);

  const [searchParams] = useSearchParams();
  const LeagueCode = searchParams.get("league");

  // Скролл вверх при смене лиги
  useEffect(() => {
    window.scrollTo({ top: 0, left: 0 });
  }, [LeagueCode]);

  // Загрузка данных
  useEffect(() => {
    const fetchAllMatches = async () => {
      setLoading(true);
      // Запрашиваем данные с бэкенда
      const data = await getMatches(LeagueCode);
      setAllMatches(data);
      setLoading(false);
    };
    fetchAllMatches();
  }, [LeagueCode]);

  // Фильтрация и сортировка
  useEffect(() => {
    let filtered = [...allMatches];

    // Сортировка по дате (ближайшие — сверху)
    filtered.sort((a, b) => new Date(a.utcDate) - new Date(b.utcDate));

    setDisplayMatches(filtered);
  }, [allMatches]);

  // Определяем текущую лигу для заголовка (ИСПРАВЛЕНО: теперь имя совпадает)
  const currentLeague =
    SidebarLeagues.find((l) => l.code === LeagueCode) || SidebarLeagues[0];

  return (
    <div className="max-w-6xl mx-auto px-4">
      <section className="w-full">
        {/* Шапка секции */}
        <div className="flex items-center justify-between mb-8 border-b border-gray-800 pb-4">
          <h1 className="text-2xl font-black text-white uppercase tracking-tighter">
            {currentLeague.name}
          </h1>
          <div className="flex items-center gap-2">
            <span className="h-2 w-2 bg-green-500 rounded-full animate-pulse"></span>
            <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">
              Live Analysis
            </span>
          </div>
        </div>

        {/* Состояние загрузки */}
        {loading ? (
          <div className="flex flex-col justify-center items-center h-64 gap-4">
            <div className="w-12 h-12 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-xs font-bold text-gray-500 uppercase tracking-widest">
              Загрузка данных нейросети...
            </p>
          </div>
        ) : displayMatches.length === 0 ? (
          /* Если матчей нет */
          <div className="text-center py-20 bg-gray-900/50 rounded-2xl border border-dashed border-gray-800">
            <p className="text-gray-500 font-medium">
              Матчи не найдены или не запланированы на ближайшее время.
            </p>
          </div>
        ) : (
          /* Список матчей */
          <MatchList
            matches={displayMatches}
            selectedLeague={LeagueCode}
            orderedLeagues={SidebarLeagues}
          />
        )}
      </section>
    </div>
  );
}

export default HomePage;
